#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the owner's steps on the platform domain's Cloudflare account (#1621).
# The runbook is infra/tofu/stacks/cloudflare/README.md (#1615); the in-cluster
# token documents are described in infra/environments/vps/secrets/README.md (#1614).
#
# The owner buys the domain, sets the registrar settings and makes three tokens.
# The wizard stores the two in-cluster tokens in sops. It prints no token, writes
# no plaintext to disk, sends each token value only through stdin to sops, and
# changes nothing without a confirmation. It never runs tofu: plan and apply stay
# the owner's, as the runbook says.
#
#   bash tools/harness/wizards/cloudflare.sh            # the real run, from the repository root
#   bash tools/harness/wizards/cloudflare.sh --dry-run  # touches nothing
#
# The domain's name is never asked for and never written: it is a run-time value
# (ADR 0164). Nothing Cloudflare-specific is provable before the domain exists.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6
# No stage writes to a dotenv file; this keeps the library's hidden-entry helpers from reading one.
ENV_FILE=/dev/null
DOCUMENTS_DIR="infra/environments/vps/secrets"
AGE_KEY_FILE="${SOPS_AGE_KEY_FILE:-$HOME/.config/sops/age/kore-vps.txt}"
TOKENS_PAGE="https://dash.cloudflare.com/profile/api-tokens"
REGISTRAR_PAGE="https://dash.cloudflare.com/?to=/:account/domains"

USAGE='Usage: cloudflare.sh [--dry-run]'
DRY_RUN=0
while (( $# )); do
  case "$1" in
    --dry-run) DRY_RUN=1 ;;
    *) printf 'Unknown option %s. %s\n' "$1" "$USAGE" >&2; exit 2 ;;
  esac
  shift
done

# In a dry run nothing is opened, read, encrypted or written, and no prompt waits.
if (( DRY_RUN )); then
  open_url() { printf '  %s[dry run]%s would open %s\n' "$DIM" "$RESET" "$1"; }
  pause()    { :; }
  confirm()  { return 0; }
fi

# store_token CONSUMER NAMESPACE DOCUMENT stores one in-cluster token as a Kubernetes
# Secret, encrypted by sops into DOCUMENT. The token travels from a hidden prompt into
# this shell's memory, then down the stdin of sops; it never reaches a file or an
# argument, and sops answers with ciphertext only, written to a temporary file that
# then replaces the document.
store_token() {
  local consumer="$1" namespace="$2" document="$3" path json tmp
  path="$DOCUMENTS_DIR/$document"
  if (( DRY_RUN )); then
    note "[dry run] would encrypt the $consumer token into $path as a Secret in $namespace, through stdin to sops"
    return 0
  fi
  if [[ -e "$path" ]]; then
    confirm "$path already holds a token. Replace it?" || {
      printf '  %s✓ kept%s %s, already stored; not changed\n' "$GREEN" "$RESET" "$path"
      return 0
    }
  fi
  ask_secret TOKEN "Paste the $consumer token (hidden):"
  # A Cloudflare token is letters, digits, _ and -, so it needs no JSON escaping. Anything else is refused unseen.
  if [[ ! "$TOKEN" =~ ^[A-Za-z0-9_-]+$ ]]; then
    unset TOKEN
    warn "that is not the shape of a Cloudflare token, so nothing was stored; paste it exactly as Cloudflare shows it"
    exit 1
  fi
  confirm "Encrypt the $consumer token into $path now?" || { unset TOKEN; exit 1; }
  json="{\"apiVersion\":\"v1\",\"kind\":\"Secret\",\"metadata\":{\"name\":\"cloudflare-token\",\"namespace\":\"$namespace\"},\"type\":\"Opaque\",\"stringData\":{\"api-token\":\"$TOKEN\"}}"
  unset TOKEN
  tmp=$(mktemp "$DOCUMENTS_DIR/.$document.XXXXXX")
  if printf '%s' "$json" | sops --encrypt --input-type json --output-type yaml --filename-override "$path" /dev/stdin > "$tmp" && [[ -s "$tmp" ]]; then
    unset json
    mv "$tmp" "$path"
    printf '  %s✓ stored%s the %s token, encrypted, at %s\n' "$GREEN" "$RESET" "$consumer" "$path"
  else
    unset json
    rm -f "$tmp"
    warn "sops could not encrypt the $consumer token; check the age key at $AGE_KEY_FILE for this environment, then rerun this step"
    exit 1
  fi
}

banner "Cloudflare account for the platform domain: the owner's steps"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check you are ready"
say "This walks the steps only you can take: buying the domain, the registrar settings, three tokens,"
say "and storing the two in-cluster tokens in sops."
note "It prints no token and writes no plaintext to disk. Each token goes only through stdin to sops."
note "Nothing Cloudflare-specific is provable until the domain exists; the offline checks are the only proof until then."
if (( DRY_RUN )); then
  note "Dry run: nothing is opened, read, encrypted or written."
else
  command -v sops >/dev/null 2>&1 || { warn "needs \`sops\` on this machine; install it, then rerun"; exit 1; }
  [[ -f "$AGE_KEY_FILE" ]] || { warn "no age key at $AGE_KEY_FILE; create it as infra/environments/vps/secrets/README.md says, then rerun"; exit 1; }
  [[ -f .sops.yaml && -d "$DOCUMENTS_DIR" ]] || { warn "run this from the repository root, where .sops.yaml and $DOCUMENTS_DIR are"; exit 1; }
  say "sops and the age key are ready, and you are in the repository root."
fi
confirm "Continue?" || exit 1

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Buy the platform domain at a Cloudflare-supported registrar"
open_url "$REGISTRAR_PAGE"
step "Register the platform domain. This wizard never asks for its name; the name stays in your run-time file."
note "Undo: cancel the registration at the registrar before the purchase is final. Decide before you buy."
confirm "The domain is registered at the registrar?" || exit 1

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Turn on the registrar lock, auto-renew and two-factor"
step "Registrar lock: on, so the domain cannot be transferred away."
step "Auto-renew: on. An expired registration takes every app down, and no expiry alert exists yet."
step "Two-factor on the Cloudflare account and the registrar account, with a hardware key."
note "Undo: switch each setting back off in the same place. This wizard changes none of them."
confirm "All three are on?" || exit 1

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Make the OpenTofu token and keep it in your password manager"
open_url "$TOKENS_PAGE"
step "Create a token with Zone · Zone Read and Zone · DNS · Edit, on the one platform zone only."
step "Expiry: 12 months, with no scheduled rotation."
step "Keep it in your password manager. This wizard never stores it; tofu reads it from CLOUDFLARE_API_TOKEN."
note "Undo: revoke the token on the same page."
confirm "The OpenTofu token is made with those scopes and kept in your password manager?" || exit 1

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Make the external-dns token and store it in sops"
open_url "$TOKENS_PAGE"
step "Create a token with Zone · Zone Read and Zone · DNS · Edit, on the one platform zone only, expiry 12 months."
note "The token goes into the kore-external-dns namespace, where external-dns reads it."
note "Undo: delete $DOCUMENTS_DIR/cloudflare-external-dns.enc.yaml and revoke the token on the same page."
store_token external-dns kore-external-dns cloudflare-external-dns.enc.yaml

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Make the acme-dns01 token and store it in sops"
open_url "$TOKENS_PAGE"
step "Create a second token with Zone · Zone Read and Zone · DNS · Edit, on the one platform zone only, expiry 12 months."
note "The token goes into the cert-manager namespace, where cert-manager reads it for DNS-01."
note "Undo: delete $DOCUMENTS_DIR/cloudflare-acme-dns01.enc.yaml and revoke the token on the same page."
store_token acme-dns01 cert-manager cloudflare-acme-dns01.enc.yaml

finish
say "Next, once the domain exists, follow the runbook (infra/tofu/stacks/cloudflare/README.md):"
say "export CLOUDFLARE_API_TOKEN from your password manager, run tofu plan, then tofu apply."
say "Then check that the DS record is published and that the chain validates; the runbook says how."
}

run_wizard "$@"; exit
